<?php
declare(strict_types=1);
$id='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';
$sql=[
"CREATE TABLE mock_registrar_domains (id $id PRIMARY KEY,account_id $id NOT NULL,name_ascii VARCHAR(253) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,create_operation_id $id NOT NULL UNIQUE,status VARCHAR(24) CHARACTER SET ascii NOT NULL CHECK(status IN ('REGISTERED','TRANSFER_PENDING')),term_years INT UNSIGNED NOT NULL CHECK(term_years BETWEEN 1 AND 10),nameservers_json LONGTEXT NOT NULL CHECK(JSON_VALID(nameservers_json)),locked BOOLEAN NOT NULL DEFAULT TRUE,privacy_enabled BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(account_id) REFERENCES domain_registrar_accounts(id)) ENGINE=InnoDB",
"CREATE TABLE mock_registrar_calls (operation_id $id PRIMARY KEY,account_id $id NOT NULL,action VARCHAR(24) CHARACTER SET ascii NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii NOT NULL,status VARCHAR(24) CHARACTER SET ascii NOT NULL CHECK(status IN ('SUCCESS','DEFINITIVE_FAILURE','UNKNOWN','UNSUPPORTED')),resource_id $id NULL,safe_code VARCHAR(64) CHARACTER SET ascii NOT NULL,no_effect BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(account_id) REFERENCES domain_registrar_accounts(id)) ENGINE=InnoDB",
];foreach(['UPDATE','DELETE'] as $verb){$sql[]='CREATE TRIGGER mock_registrar_calls_'.strtolower($verb)." BEFORE $verb ON mock_registrar_calls FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable mock registrar call'";}return $sql;
